SELECT
 (SELECT count(*)=3 AND bool_and(c.relrowsecurity) FROM pg_class c WHERE c.oid IN(to_regclass('petro_private.service_product_returns'),to_regclass('petro_private.service_product_return_inspections'),to_regclass('petro_private.service_product_return_commands')))
 AND NOT EXISTS(SELECT 1 FROM pg_class c CROSS JOIN(VALUES('anon'),('authenticated'),('service_role'))r(name) WHERE c.oid IN(to_regclass('petro_private.service_product_returns'),to_regclass('petro_private.service_product_return_inspections'),to_regclass('petro_private.service_product_return_commands')) AND has_table_privilege(r.name,c.oid,'SELECT,INSERT,UPDATE,DELETE'))
 AND(SELECT count(*)=4 AND bool_and(p.prosecdef AND p.proconfig=ARRAY['search_path=""']::text[] AND has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p WHERE p.oid IN(to_regprocedure('public.petro_service_product_returns(uuid,integer)'),to_regprocedure('public.petro_service_product_return_inspections(uuid,integer)'),to_regprocedure('public.petro_receive_service_product_return(uuid,bigint,uuid,text,text,text)'),to_regprocedure('public.petro_inspect_service_product_return(uuid,bigint,uuid,text,text,text,text)')))
 AND(SELECT count(*)=3 FROM pg_trigger WHERE NOT tgisinternal AND tgenabled='O' AND tgname IN('service_product_return_immutable','service_product_return_inspection_immutable','service_product_return_command_immutable'))
 AND(SELECT count(*)=1 AND bool_and(NOT p.prosecdef AND p.proconfig=ARRAY['search_path=""']::text[] AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p WHERE p.oid=to_regprocedure('petro_private.guard_service_product_return_history()'))
 AS present;
